for v in [W['puisque']]:
 v['example']=ex('Puisque vous êtes disponible samedi, je voudrais venir samedi.','Поскольку вы свободны в субботу, я хотел бы прийти в субботу.','пюиск ву зэт диспонибль самди, жё вудрэ вэнир самди́')
 v['review_items'][1]['choices'][0]=dict(id='c0',**fr(v['example']['fr'],v['example']['transcription_ru']))
for w,g,b in [('a-mon-avis','Оценка отмечена как личное мнение.','Подтверждение встречи и условие доступности выполняют другие функции.'),('argument','Назван довод, поддерживающий позицию.','В этой теме речь о доводе, а не о ссоре; встреча и крайний срок называют другие детали.'),('puisque','Известная доступность использована как основание желания прийти.','Вопрос о доступности её ещё не устанавливает; подтверждение само по себе не называет причину.'),('donc','Выбор кафе представлен как следствие его тишины.','Личная оценка и уточнение тарифа не выражают этот вывод.'),('en-effet','Предыдущая оценка подкрепляется опытом работы в кафе.','Условие и временная граница не подтверждают оценку.'),('par-exemple','Назван конкретный случай подготовки сообщения.','Личная оценка и подтверждение встречи не вводят пример.'),('cependant','К положительной оценке добавлена оговорка о цене.','Вывод о тишине и пример не передают противопоставление.'),('pourtant','Предпочтение дома противопоставлено ожидаемому выбору близкого кафе.','Полезная причина и пример не выражают это противопоставление.')]:W[w]['review_items'][1]['feedback']=fb(g,b)

